preguntas = [
    ("¿Cuántos libros tiene la Biblia? ", "66"),
    ("¿Quién construyó el arca? ", "Noé"),
    ("¿En qué ciudad nació Pablo? ", "Tarso"),
]
puntos = 0
for pregunta, respuesta in preguntas:
    r = input(pregunta)
    if r.strip().lower() == respuesta.lower():
        print("¡Correcto!")
    else:
        print("La respuesta es:", respuesta)
print(f"Puntuación: {puntos} de {len(preguntas)}")

