import math

CAPITULOS = 1189

def capitulos_por_dia(dias):
    return math.ceil(CAPITULOS / dias)

try:
    dias = int(input("¿En cuántos días quieres leer la Biblia? "))
    if dias <= 0:
        raise ValueError
    por_dia = capitulos_por_dia(dias)
    print(f"Lee {por_dia} capítulos al día")
    print(f"Terminarás en {math.ceil(CAPITULOS / por_dia)} días")
except ValueError:
    print("Escribe un número entero mayor que 0")

