def _ref(t, a):
    r, act = [], ''
    for p in t.split():
        if not act: act = p
        elif len(act) + 1 + len(p) <= a: act += ' ' + p
        else: r.append(act); act = p
    if act: r.append(act)
    return r
import json as _j
_v = _j.load(open('versiculos.json', encoding='utf-8'))['col-3-23']['es']
for _a in (10, 20, 30, 45):
    assert partir(_v['texto'], _a) == _ref(_v['texto'], _a)

